mapper.update:
update course
course_name = #{courseName}, teacher_id = #{teacherId}, classroom_id = #{classroomId}, weekday = #{weekday}, start_week = #{startWeek}, end_week = #{endWeek},
where course_id = #{courseId}

mapper.select:
select * from course


        and course_id like concat('%', #{courseId}, '%')


        and course_name like concat('%', #{courseName}, '%')


        and teacher_id = #{teacherId}


        and classroom_id = #{classroomId}


order by create_time desc
